EBOOK_HTML = """<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ebooks</title><style>body{background:#0e0e14;color:white;font-family:Arial;padding:12px}.card{background:#1a1a25;border:1px solid #2a2a3a;padding:14px;border-radius:10px;margin:8px 0}button{padding:8px 14px;border:none;border-radius:6px;font-weight:bold}input{padding:8px;background:#1e1e2d;color:white;border:1px solid #333;border-radius:5px}</style></head><body><a href="/" style="color:#f9c846">← Home</a><h2 style="color:#f9c846">📚 Ebook Store - Real PDFs</h2><div class="card" style="border:1px dashed #f9c846"><h3>📤 Upload PDF (Admin)</h3><form id="upForm" enctype="multipart/form-data"><input type="text" id="eTitle" placeholder="Title" required style="width:100%"><input type="number" id="ePrice" placeholder="Price $" required style="width:100%;margin-top:6px"><input type="file" id="pdfFile" accept=".pdf" required style="width:100%;margin-top:6px"><button type="submit" style="background:#f9c846;color:black;width:100%;margin-top:8px">Upload</button></form><p id="upStatus"></p></div><div id="ebookList">Loading...</div><script>async function loadEbooks(){let res=await fetch('/api/ebooks');let data=await res.json();document.getElementById('ebookList').innerHTML=data.map(e=>`<div class="card"><h3>${e.title} - $${e.price}</h3><button onclick="buyEbook('${e.filename}','${e.title}',${e.price})" style="background:#00c950;color:white">Buy & Download</button> <a href="/download/${e.filename}" target="_blank" style="color:#aaa;font-size:12px">Preview</a></div>`).join('')||'<p>No ebooks yet</p>';}async function buyEbook(filename,title,price){let bal=parseFloat(localStorage.getItem('bal')||'0');if(bal<price){alert('Low balance! Deposit in Trading first');return;}if(!confirm('Buy '+title+' for $'+price+'?')) return;bal-=price;localStorage.setItem('bal',bal);let admin=parseFloat(localStorage.getItem('adminBal')||'0');admin+=price;localStorage.setItem('adminBal',admin);let eb=parseFloat(localStorage.getItem('admin_ebook')||'0');localStorage.setItem('admin_ebook',eb+price);window.location='/download/'+filename;}document.getElementById('upForm').onsubmit=async(e)=>{e.preventDefault();let fd=new FormData();fd.append('title',document.getElementById('eTitle').value);fd.append('price',document.getElementById('ePrice').value);fd.append('file',document.getElementById('pdfFile').files[0]);document.getElementById('upStatus').innerText='Uploading...';let res=await fetch('/upload_ebook',{method:'POST',body:fd});let d=await res.json();document.getElementById('upStatus').innerText=d.message;if(d.ok) loadEbooks();};loadEbooks();</script></body></html>"""

